mapper.select:
, ranked_member AS ( SELECT member.id AS membership_id, member.group_id, tree.group_name, member.agent_id, agent.work_no, agent.agent_name, agent.phone_number, member.member_role, member.priority, agent.role_code, agent.status, member.created_at, tree.depth, ROW_NUMBER() OVER ( PARTITION BY member.agent_id ORDER BY tree.depth, member.priority, member.id ) AS member_rank FROM group_tree tree JOIN fcc_agent_group_member member ON member.group_id = tree.id AND member.deleted_at IS NULL JOIN fcc_agent agent ON agent.id = member.agent_id AND agent.deleted_at IS NULL
AND (agent.agent_name LIKE CONCAT('%', #{keyword}, '%') OR agent.work_no LIKE CONCAT('%', #{keyword}, '%') OR agent.phone_number LIKE CONCAT('%', #{keyword}, '%'))
) SELECT membership_id, group_id, group_name, agent_id, work_no, agent_name, phone_number, member_role, priority, role_code, status, created_at FROM ranked_member WHERE member_rank = 1 ORDER BY depth, priority, work_no, agent_id LIMIT #{limit} OFFSET #{offset}
